const MARKS = {}; for (const [b, m] of Object.entries({ a: 'āáǎà', e: 'ēéěè', i: 'īíǐì', o: 'ōóǒò', u: 'ūúǔù', ü: 'ǖǘǚǜ' })) [...m].forEach((c, i) => (MARKS[c] = [b, i + 1]));
