        u.rate = rate || S.settings.rate; u.pitch = 1;
        u.onend = u.onerror = () => { clearTimeout(this.dog); if (this.u === u) this.u = null; };
        this.u = u; // keep a reference: iOS garbage-collects utterances mid-speech and the queue freezes
