  if (b.dataset.s === 'srate') { SES.srate = +b.dataset.v; stopLines(); return renderStory(cur()); }
  if (b.dataset.s === 'stxt') { SES.stxt = +b.dataset.v; stopLines(); return renderStory(cur()); }
