    shuffle(grp).forEach(i => { const it = (Math.random() < .55 || !voiceOK() ? cxBuildItem(i, ord[i][2]) : null) || cxLMean(i, ord[i][2], ws) || cxBuildItem(i, ord[i][0]); if (it) out.push(it); });
