  if (a === 'sayex') { e.stopPropagation(); const v = klVocab(FC.ids[FC.i]); if (v && v.ex) TTS.speak(v.ex.zh); return; }
  if (a === 'flip') { FC.flip = !FC.flip; FX.play('flip'); fcRender(); if (FC.flip && S.settings.autoplay) say(W[FC.ids[FC.i]]); return; }
