  food: [['甜點', 'tián diǎn'], ['蛋糕', 'dàn gāo'], ['巧克力', 'qiǎo kè lì'], ['炒飯', 'chǎo fàn'], ['拉麵', 'lā miàn'], ['炸雞', 'zhá jī'], ['麵包', 'miàn bāo'], ['雞肉', 'jī ròu']],
  like: [['看電視', 'kàn diàn shì'], ['看書', 'kàn shū'], ['看電影', 'kàn diàn yǐng'], ['寫字', 'xiě zì'], ['喝奶茶', 'hē nǎi chá'], ['喝咖啡', 'hē kā fēi']]
