  const lvl = Math.floor(p.streak / 3);
  const n = x.s.chunks.length;
  p.mode = 'combo'; p.cb = { s: x.s, order: x.order, k: 0, used: new Set(), lvl, until: Date.now() + 6000 + n * 1900, t0: Date.now() };
  p.cb.dur = p.cb.until - p.cb.t0;
