      <span class="grow" style="min-width:0"><b><span class="hz">${M.zh}</span> · ${t(M.ti)}</b>${cur0 ? `<span class="small muted">${t(M.sub)}</span>` : ''}<span class="small muted">±${M.min} ${t('menit')}${extra}</span></span>
