  if (!due.length || free) { isFree = true; const all = Object.entries(kbS().rv).map(([key, v]) => ({ key, n: +key.split('-')[0], k: key.split('-')[1], s: v.s })).filter(x => KL(x.n)); due = shuffle(all).sort((a, b) => a.s - b.s).slice(0, 3); }
