    n.textContent = seq[k]; n.classList.remove('pop'); void n.offsetWidth; n.classList.add('pop');
    lgBeep(k < 3 ? 660 : 990, k < 3 ? 0.1 : 0.25, 'triangle', 0.08); k++; LG.cd = setTimeout(step, k === seq.length ? 520 : 640);
