    for (let tries = 0; tries < ws.length && !it; tries++) { const x = ws[j++ % ws.length]; it = tmQ(T, x, qt); if (!it && qt === 'order') { const g = pick(T.grammar || [{}]); const e = g.ex && pick(g.ex); it = e ? tmBuild(e, x) : null; } }
