  const vo = voiceOK(); const out = [];
  shuffle(xs).forEach((x, j) => { const it = tmMcq(T, x, ['hz2mean', 'mean2hz', vo ? 'audio2hz' : 'py2hz'][j % 3], true); if (it) out.push(it); });
