      pool, root, cv: root.querySelector('canvas'), mode: a.bo.m || 'mix', diff: clamp(+a.bo.d || 1, 0, 2), musicOn: a.bo.mu !== 0,
      phase: 'setup', t: 0, last: 0, raf: 0, evts: [], parts: [], floats: [], speed: [], paused: false, alive: true, shake: 0, flash: 0,
