    if (cho || pre || post) { const pt = pre ? [0, 1, 2, 3, 1, 2, 3, 4, 2, 3, 4, 5, 3, 4, 5, 5] : [0, 2, 1, 3, 2, 4, 3, 2, 0, 2, 1, 3, 2, 4, 3, 4]; I.pluck(at, T + tn[pt[s]], s16 * 0.9, cho ? 0.032 : 0.036, P); }
    /* melodi */
