  const m3 = { KeyD: 0, KeyF: 1, KeyJ: 2, KeyK: 2, Digit1: 0, Digit2: 1, Digit3: 2, ArrowLeft: 0, ArrowDown: 1, ArrowUp: 1, ArrowRight: 2, Numpad1: 0, Numpad2: 1, Numpad3: 2 };
