      T.g = { off, w, g: KAL_GAP[w] ? 1 : 0, i: lgIdx().form.get(w) }; T.opts = (Array.isArray(o.o) ? o.o : []).slice(0, 6).map(x => str(x, 6)); if (!T.opts.includes(w)) T.opts.push(w);
